insert into public.actions (code,labels,prompt_texts,needs_image,sort_order,required_plan_slug,published) values ('AC-01','{"en":"Transform this architectural render into an ultra-realistic architectural photograph.","es":"Conversión de render a fotografía","pt":"Conversão de render para fotografia"}'::jsonb,'{"en":"Transform this architectural render into an ultra-realistic architectural photograph.","es":"Transforma este render arquitectónico en una fotografía arquitectónica ultra realista.","pt":"Transforme este render arquitetônico em uma fotografia arquitetônica ultra-realista."}'::jsonb,true,0,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,needs_image=excluded.needs_image,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.actions (code,labels,prompt_texts,needs_image,sort_order,required_plan_slug,published) values ('AC-02','{"en":"Transform this SketchUp viewport into an ultra-realistic architectural photograph.","es":"Desde SketchUp","pt":"A partir do SketchUp"}'::jsonb,'{"en":"Transform this SketchUp viewport into an ultra-realistic architectural photograph.","es":"Transforma esta vista de SketchUp en una fotografía arquitectónica ultra realista.","pt":"Transforme esta vista do SketchUp em uma fotografia arquitetônica ultra-realista."}'::jsonb,true,1,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,needs_image=excluded.needs_image,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.actions (code,labels,prompt_texts,needs_image,sort_order,required_plan_slug,published) values ('AC-03','{"en":"Generate an ultra-realistic architectural visualization from this conceptual sketch.","es":"Desde un croquis","pt":"A partir de um esboço"}'::jsonb,'{"en":"Generate an ultra-realistic architectural visualization from this conceptual sketch.","es":"Genera una visualización arquitectónica ultra realista a partir de este croquis conceptual.","pt":"Gere uma visualização arquitetônica ultra-realista a partir deste esboço conceitual."}'::jsonb,true,2,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,needs_image=excluded.needs_image,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.actions (code,labels,prompt_texts,needs_image,sort_order,required_plan_slug,published) values ('AC-04','{"en":"Enhance and reinterpret this architectural render into a photorealistic final image.","es":"Desde un render existente","pt":"A partir de um render existente"}'::jsonb,'{"en":"Enhance and reinterpret this architectural render into a photorealistic final image.","es":"Mejora y reinterpreta este render arquitectónico como una imagen final fotorrealista.","pt":"Aprimore e reinterprete este render arquitetônico como uma imagem final fotorrealista."}'::jsonb,true,3,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,needs_image=excluded.needs_image,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.actions (code,labels,prompt_texts,needs_image,sort_order,required_plan_slug,published) values ('AC-05','{"en":"Generate a new photorealistic architectural render based on this reference image.","es":"Desde una imagen de referencia","pt":"A partir de uma imagem de referência"}'::jsonb,'{"en":"Generate a new photorealistic architectural render based on this reference image.","es":"Genera un nuevo render arquitectónico fotorrealista basado en esta imagen de referencia.","pt":"Gere um novo render arquitetônico fotorrealista com base nesta imagem de referência."}'::jsonb,true,4,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,needs_image=excluded.needs_image,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.actions (code,labels,prompt_texts,needs_image,sort_order,required_plan_slug,published) values ('AC-06','{"en":"Generate a photorealistic architectural visualization.","es":"Generar desde cero","pt":"Gerar do zero"}'::jsonb,'{"en":"Generate a photorealistic architectural visualization.","es":"Genera una visualización arquitectónica fotorrealista.","pt":"Gere uma visualização arquitetônica fotorrealista."}'::jsonb,false,5,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,needs_image=excluded.needs_image,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.actions (code,labels,prompt_texts,needs_image,sort_order,required_plan_slug,published) values ('AC-07','{"en":"Using the provided architectural model as the base geometry, apply the visual style, materials, color palette and atmosphere from the reference image.","es":"Modelo base + imagen de estilo","pt":"Modelo base + imagem de estilo"}'::jsonb,'{"en":"Using the provided architectural model as the base geometry, apply the visual style, materials, color palette and atmosphere from the reference image.","es":"Usando el modelo arquitectónico proporcionado como geometría base, aplica el estilo visual, los materiales, la paleta de color y la atmósfera de la imagen de referencia.","pt":"Usando o modelo arquitetônico fornecido como geometria base, aplique o estilo visual, os materiais, a paleta de cores e a atmosfera da imagem de referência."}'::jsonb,true,6,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,needs_image=excluded.needs_image,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.preservations (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('PR-01','{"en":"Strictly preserve the original geometry, proportions, composition and spatial layout. Do not alter structural elements, openings or volumetric relationships. Apply only surface-level changes such as materials, lighting and atmosphere.","es":"Client Safe Mode · Preservación total","pt":"Client Safe Mode · Preservação total"}'::jsonb,'{"en":"Strictly preserve the original geometry, proportions, composition and spatial layout. Do not alter structural elements, openings or volumetric relationships. Apply only surface-level changes such as materials, lighting and atmosphere.","es":"Preserva estrictamente la geometría original, las proporciones, la composición y la organización espacial. No alteres elementos estructurales, aberturas ni relaciones volumétricas. Aplica únicamente cambios superficiales como materiales, iluminación y atmósfera.","pt":"Preserve estritamente a geometria original, as proporções, a composição e a organização espacial. Não altere elementos estruturais, aberturas nem relações volumétricas. Aplique apenas mudanças superficiais, como materiais, iluminação e atmosfera."}'::jsonb,'{"es":"Preserva estrictamente la geometría, proporciones y composición. Solo cambia materiales, luz y atmósfera. Úsalo cuando la fidelidad al modelo es crítica (presentación a cliente, concurso).","pt":"Preserva estritamente a geometria, proporções e composição. Altera apenas materiais, luz e atmosfera. Use quando a fidelidade ao modelo é crítica."}'::jsonb,0,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.preservations (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('PR-02','{"en":"Maintain the overall composition and primary structural elements. Allow creative reinterpretation of materials, lighting, atmosphere and secondary details. If a style reference image is provided, extract its color palette, material language and mood and apply them to the base model.","es":"Studio Render Mode · Preservación flexible","pt":"Studio Render Mode · Preservação flexível"}'::jsonb,'{"en":"Maintain the overall composition and primary structural elements. Allow creative reinterpretation of materials, lighting, atmosphere and secondary details. If a style reference image is provided, extract its color palette, material language and mood and apply them to the base model.","es":"Mantén la composición general y los elementos estructurales principales. Permite una reinterpretación creativa de materiales, iluminación, atmósfera y detalles secundarios. Si se proporciona una imagen de estilo, extrae su paleta cromática, lenguaje material y mood, y aplícalos al modelo base.","pt":"Mantenha a composição geral e os principais elementos estruturais. Permita uma reinterpretação criativa de materiais, iluminação, atmosfera e detalhes secundários. Se uma imagem de estilo for fornecida, extraia sua paleta cromática, linguagem material e mood, e aplique ao modelo base."}'::jsonb,'{"es":"Mantén la composición general y la estructura principal. Si hay imagen de estilo (AC-07), extrae su paleta, materiales y atmósfera y aplicálos al modelo base. Buen equilibrio entre fidelidad y calidad visual.","pt":"Mantenha a composição geral e a estrutura principal. Se houver imagem de estilo (AC-07), extraia sua paleta, materiais e atmosfera e aplique ao modelo base."}'::jsonb,1,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.preservations (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('PR-03','{"en":"Use the base model only as a loose spatial reference. Freely reinterpret all materials, lighting, atmosphere, entourage and secondary elements to achieve the highest visual quality. If a style reference image is provided, fully absorb its aesthetic language.","es":"Concept Freedom Mode · Libertad creativa","pt":"Concept Freedom Mode · Liberdade criativa"}'::jsonb,'{"en":"Use the base model only as a loose spatial reference. Freely reinterpret all materials, lighting, atmosphere, entourage and secondary elements to achieve the highest visual quality. If a style reference image is provided, fully absorb its aesthetic language.","es":"Usa el modelo base solo como una referencia espacial flexible. Reinterpreta libremente materiales, iluminación, atmósfera, elementos de escala y detalles secundarios para lograr la máxima calidad visual. Si se proporciona una imagen de estilo, absorbe completamente su lenguaje estético.","pt":"Use o modelo base apenas como uma referência espacial flexível. Reinterprete livremente materiais, iluminação, atmosfera, elementos de escala e detalhes secundários para alcançar a máxima qualidade visual. Se uma imagem de estilo for fornecida, absorva completamente sua linguagem estética."}'::jsonb,'{"es":"El modelo es solo referencia espacial. Si hay imagen de estilo (AC-07), absorbé completamente su lenguaje estético. Máxima calidad visual, mínima restricción geométrica. Ideal para exploración conceptual.","pt":"O modelo é apenas referência espacial. Se houver imagem de estilo (AC-07), absorva completamente sua linguagem estética. Máxima qualidade visual, mínima restrição geométrica."}'::jsonb,2,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.style_dimensions (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('SD-01','{"en":"Extract only the material palette from the reference image: surface finishes, textures, and material combinations. Do not transfer its lighting, atmosphere or landscape.","es":"Solo materiales","pt":"Apenas materiais"}'::jsonb,'{"en":"Extract only the material palette from the reference image: surface finishes, textures, and material combinations. Do not transfer its lighting, atmosphere or landscape.","es":"Extrae únicamente la paleta material de la imagen de referencia: terminaciones, texturas y combinaciones de materiales. No transfieras su iluminación, atmósfera ni paisaje.","pt":"Extraia apenas a paleta material da imagem de referência: acabamentos, texturas e combinações de materiais. Não transfira sua iluminação, atmosfera nem paisagem."}'::jsonb,'{"es":"Toma únicamente los materiales y texturas de la imagen de referencia. No transfiere su luz, atmósfera ni entorno.","pt":"Extrai apenas os materiais e texturas da imagem de referência. Não transfere luz, atmosfera nem entorno."}'::jsonb,0,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.style_dimensions (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('SD-02','{"en":"Extract only the color palette from the reference image: dominant hues, tonal range, warm/cool balance and color relationships. Do not transfer its materials, lighting setup or spatial composition.","es":"Solo paleta de color","pt":"Apenas paleta de cor"}'::jsonb,'{"en":"Extract only the color palette from the reference image: dominant hues, tonal range, warm/cool balance and color relationships. Do not transfer its materials, lighting setup or spatial composition.","es":"Extrae únicamente la paleta de color de la imagen de referencia: tonos dominantes, rango tonal, equilibrio cálido/frío y relaciones cromáticas. No transfieras sus materiales, iluminación ni composición espacial.","pt":"Extraia apenas a paleta de cores da imagem de referência: tons dominantes, faixa tonal, equilíbrio quente/frio e relações cromáticas. Não transfira seus materiais, iluminação nem composição espacial."}'::jsonb,'{"es":"Toma únicamente la paleta cromática: colores dominantes, equilibrio cálido/frío y relaciones de color. No transfiere materiales ni iluminación.","pt":"Extrai apenas a paleta cromática: cores dominantes, equilíbrio quente/frio e relações de cor. Não transfere materiais nem iluminação."}'::jsonb,1,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.style_dimensions (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('SD-03','{"en":"Extract only the landscape and surrounding context from the reference image: vegetation, terrain, sky and environmental elements. Do not transfer its materials, interior finishes or lighting setup.","es":"Solo entorno / paisaje","pt":"Apenas entorno / paisagem"}'::jsonb,'{"en":"Extract only the landscape and surrounding context from the reference image: vegetation, terrain, sky and environmental elements. Do not transfer its materials, interior finishes or lighting setup.","es":"Extrae únicamente el paisaje y el contexto de la imagen de referencia: vegetación, terreno, cielo y elementos ambientales. No transfieras sus materiales, terminaciones interiores ni iluminación artificial.","pt":"Extraia apenas a paisagem e o contexto da imagem de referência: vegetação, terreno, céu e elementos ambientais. Não transfira seus materiais, acabamentos interiores nem iluminação artificial."}'::jsonb,'{"es":"Toma únicamente el entorno: vegetación, terreno, cielo y elementos ambientales. No transfiere materiales, interiores ni iluminación artificial.","pt":"Extrai apenas o entorno: vegetação, terreno, céu e elementos ambientais. Não transfere materiais, interiores nem iluminação artificial."}'::jsonb,2,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.style_dimensions (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('SD-04','{"en":"Extract only the lighting quality and weather conditions from the reference image: light direction, intensity, time of day, shadow quality and atmospheric conditions. Do not transfer its materials or landscape.","es":"Solo luz y clima","pt":"Apenas luz e clima"}'::jsonb,'{"en":"Extract only the lighting quality and weather conditions from the reference image: light direction, intensity, time of day, shadow quality and atmospheric conditions. Do not transfer its materials or landscape.","es":"Extrae únicamente la calidad de luz y las condiciones climáticas de la imagen de referencia: dirección, intensidad, hora del día, calidad de sombra y atmósfera. No transfieras sus materiales ni paisaje.","pt":"Extraia apenas a qualidade da luz e as condições climáticas da imagem de referência: direção, intensidade, hora do dia, qualidade das sombras e atmosfera. Não transfira seus materiais nem paisagem."}'::jsonb,'{"es":"Toma únicamente la calidad de luz y las condiciones climáticas: dirección, intensidad, hora del día, calidad de sombras. No transfiere materiales ni paisaje.","pt":"Extrai apenas a qualidade de luz e condições climáticas: direção, intensidade, hora do dia, qualidade de sombras. Não transfere materiais nem paisagem."}'::jsonb,3,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.style_dimensions (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('SD-05','{"en":"Extract the overall mood and atmosphere from the reference image: emotional tone, sense of scale, human presence and narrative quality. Apply this feeling to the base model without replicating specific materials or landscape.","es":"Solo atmósfera / mood","pt":"Apenas atmosfera / mood"}'::jsonb,'{"en":"Extract the overall mood and atmosphere from the reference image: emotional tone, sense of scale, human presence and narrative quality. Apply this feeling to the base model without replicating specific materials or landscape.","es":"Extrae el mood general y la atmósfera de la imagen de referencia: tono emocional, sensación de escala, presencia humana y calidad narrativa. Aplica esa sensación al modelo base sin copiar materiales ni paisaje específicos.","pt":"Extraia o mood geral e a atmosfera da imagem de referência: tom emocional, sensação de escala, presença humana e qualidade narrativa. Aplique essa sensação ao modelo base sem copiar materiais nem paisagem específicos."}'::jsonb,'{"es":"Toma únicamente el mood: tono emocional, escala, presencia humana y calidad narrativa. Sin replicar materiales específicos ni paisaje.","pt":"Extrai apenas o mood: tom emocional, escala, presença humana e qualidade narrativa. Sem replicar materiais específicos nem paisagem."}'::jsonb,4,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.style_dimensions (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('SD-06','{"en":"Extract only the architectural style language from the reference image: formal composition, massing relationships, facade rhythm and proportional system. Do not transfer its specific materials or color palette.","es":"Solo lenguaje arquitectónico","pt":"Apenas linguagem arquitetônica"}'::jsonb,'{"en":"Extract only the architectural style language from the reference image: formal composition, massing relationships, facade rhythm and proportional system. Do not transfer its specific materials or color palette.","es":"Extrae únicamente el lenguaje arquitectónico de la imagen de referencia: composición formal, relaciones de masa, ritmo de fachada y sistema proporcional. No transfieras materiales ni paleta cromática específicos.","pt":"Extraia apenas a linguagem arquitetônica da imagem de referência: composição formal, relações de massa, ritmo de fachada e sistema proporcional. Não transfira materiais nem paleta cromática específicos."}'::jsonb,'{"es":"Toma únicamente el lenguaje arquitectónico: composición formal, relaciones de masa, ritmo de fachada y sistema de proporciones. Sin materiales ni paleta específicos.","pt":"Extrai apenas a linguagem arquitetônica: composição formal, relações de massa, ritmo de fachada e sistema de proporções. Sem materiais nem paleta específicos."}'::jsonb,5,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.style_dimensions (code,labels,prompt_texts,descriptions,sort_order,required_plan_slug,published) values ('SD-07','{"en":"Extract the photographic and rendering style from the reference image: camera angle, lens characteristics, depth of field, post-processing style and overall visual treatment.","es":"Solo estilo fotográfico / render","pt":"Apenas estilo fotográfico / render"}'::jsonb,'{"en":"Extract the photographic and rendering style from the reference image: camera angle, lens characteristics, depth of field, post-processing style and overall visual treatment.","es":"Extrae el estilo fotográfico y de render de la imagen de referencia: ángulo de cámara, características de lente, profundidad de campo, posproducción y tratamiento visual general.","pt":"Extraia o estilo fotográfico e de render da imagem de referência: ângulo de câmera, características da lente, profundidade de campo, pós-produção e tratamento visual geral."}'::jsonb,'{"es":"Toma únicamente el estilo fotográfico: ángulo de cámara, características de lente, profundidad de campo y tratamiento visual general.","pt":"Extrai apenas o estilo fotográfico: ângulo de câmera, características de lente, profundidade de campo e tratamento visual geral."}'::jsonb,6,'studio_pro',true) on conflict (code) do update set labels=excluded.labels,prompt_texts=excluded.prompt_texts,descriptions=excluded.descriptions,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
