insert into public.recipes (code,names,descriptions,config,sort_order,required_plan_slug,published) values ('R-02','{"en":"Base model + Pinterest reference","es":"Modelo base + referencia Pinterest","pt":"Modelo base + referência Pinterest"}'::jsonb,'{"en":"Transfers style without losing the original project.","es":"Transfiere estilo sin perder el proyecto original.","pt":"Transfere estilo sem perder o projeto original."}'::jsonb,'{"code":"R-02","name":{"en":"Base model + Pinterest reference","es":"Modelo base + referencia Pinterest","pt":"Modelo base + referência Pinterest"},"desc":{"en":"Transfers style without losing the original project.","es":"Transfiere estilo sin perder el proyecto original.","pt":"Transfere estilo sem perder o projeto original."},"accion":"AC-07","pres":"PR-01","output":"gpt","styleDims":["SD-01","SD-02","SD-04","SD-07"],"sel":{"V":"V-01","C":"C-08","A":"A-03","L":"L-04"},"multi":{"M":["M-02","M-06"]}}'::jsonb,1,'studio_pro',true) on conflict (code) do update set names=excluded.names,descriptions=excluded.descriptions,config=excluded.config,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
