insert into public.recipes (code,names,descriptions,config,sort_order,required_plan_slug,published) values ('R-05','{"en":"Perspective section narrative","es":"Corte perspectivado narrativo","pt":"Corte perspectivado narrativo"}'::jsonb,'{"en":"Clear cut-plane logic with people, depth and atmosphere.","es":"Lógica de corte clara con personas, profundidad y atmósfera.","pt":"Lógica de corte clara com pessoas, profundidade e atmosfera."}'::jsonb,'{"code":"R-05","name":{"en":"Perspective section narrative","es":"Corte perspectivado narrativo","pt":"Corte perspectivado narrativo"},"desc":{"en":"Clear cut-plane logic with people, depth and atmosphere.","es":"Lógica de corte clara con personas, profundidad y atmósfera.","pt":"Lógica de corte clara com pessoas, profundidade e atmosfera."},"accion":"AC-04","pres":"PR-01","output":"gpt","sel":{"V":"V-02","C":"C-15","A":"A-08","L":"L-03","T":"T-07"},"multi":{"M":["M-01","M-02"]}}'::jsonb,4,'studio_pro',true) on conflict (code) do update set names=excluded.names,descriptions=excluded.descriptions,config=excluded.config,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.recipes (code,names,descriptions,config,sort_order,required_plan_slug,published) values ('R-06','{"en":"Real estate hero image","es":"Imagen hero inmobiliaria","pt":"Imagem hero imobiliária"}'::jsonb,'{"en":"Clean, commercial, bright and easy to read.","es":"Limpia, comercial, luminosa y fácil de leer.","pt":"Limpa, comercial, luminosa e fácil de ler."}'::jsonb,'{"code":"R-06","name":{"en":"Real estate hero image","es":"Imagen hero inmobiliaria","pt":"Imagem hero imobiliária"},"desc":{"en":"Clean, commercial, bright and easy to read.","es":"Limpia, comercial, luminosa y fácil de leer.","pt":"Limpa, comercial, luminosa e fácil de ler."},"accion":"AC-01","pres":"PR-01","output":"midjourney","sel":{"V":"V-01","C":"C-01","A":"A-01","L":"L-01","T":"T-02"},"multi":{"M":["M-02","M-06","M-07"]}}'::jsonb,5,'studio_pro',true) on conflict (code) do update set names=excluded.names,descriptions=excluded.descriptions,config=excluded.config,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.quality_groups (key,labels,tags,optimal_tags,sort_order,required_plan_slug,published) values ('nivel_profesional','{"en":"Professional level","es":"Nivel profesional","pt":"Nível profissional"}'::jsonb,'[{"en":"ultra-photorealistic","es":"ultra-fotorrealista","pt":"ultra-fotorrealista"},{"en":"hyper-realistic","es":"híper-realista","pt":"híper-realista"},{"en":"photorealistic","es":"fotorrealista","pt":"fotorrealista"},{"en":"extremely realistic","es":"extremadamente realista","pt":"extremamente realista"},{"en":"high-end visualization","es":"visualización de alto nivel","pt":"visualização de alto nível"},{"en":"premium visualization","es":"visualización premium","pt":"visualização premium"},{"en":"competition-quality","es":"calidad de concurso","pt":"qualidade de concurso"},{"en":"award-winning quality","es":"calidad premiada","pt":"qualidade premiada"},{"en":"studio-quality","es":"calidad de estudio","pt":"qualidade de estúdio"},{"en":"production-quality","es":"calidad de producción","pt":"qualidade de produção"},{"en":"publication-ready","es":"listo para publicación","pt":"pronto para publicação"},{"en":"gallery-quality","es":"calidad de galería","pt":"qualidade de galeria"}]'::jsonb,'["ultra-photorealistic","high-end visualization"]'::jsonb,0,'studio_pro',true) on conflict (key) do update set labels=excluded.labels,tags=excluded.tags,optimal_tags=excluded.optimal_tags,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.quality_groups (key,labels,tags,optimal_tags,sort_order,required_plan_slug,published) values ('calidad_tecnica','{"en":"Technical quality","es":"Calidad técnica","pt":"Qualidade técnica"}'::jsonb,'[{"en":"physically accurate rendering","es":"render físicamente preciso","pt":"render fisicamente preciso"},{"en":"physically based materials (PBR)","es":"materiales basados en física (PBR)","pt":"materiais baseados em física (PBR)"},{"en":"accurate global illumination","es":"iluminación global precisa","pt":"iluminação global precisa"},{"en":"ray-traced reflections","es":"reflexiones trazadas por rayos","pt":"reflexos com ray-tracing"},{"en":"soft realistic shadows","es":"sombras suaves y realistas","pt":"sombras suaves e realistas"},{"en":"high dynamic range lighting (HDRI)","es":"iluminación de alto rango dinámico (HDRI)","pt":"iluminação de alto alcance dinâmico (HDRI)"},{"en":"cinematic color grading","es":"gradación de color cinematográfica","pt":"gradação de cor cinematográfica"},{"en":"natural white balance","es":"balance de blancos natural","pt":"balanço de branco natural"},{"en":"realistic exposure","es":"exposición realista","pt":"exposição realista"},{"en":"professional post-processing","es":"postprocesado profesional","pt":"pós-processamento profissional"},{"en":"subsurface scattering","es":"dispersión subsuperficial","pt":"dispersão subsuperficial"},{"en":"ambient occlusion","es":"oclusión ambiental","pt":"oclusão ambiental"}]'::jsonb,'["physically based materials (PBR)","accurate global illumination","soft realistic shadows"]'::jsonb,1,'studio_pro',true) on conflict (key) do update set labels=excluded.labels,tags=excluded.tags,optimal_tags=excluded.optimal_tags,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.quality_groups (key,labels,tags,optimal_tags,sort_order,required_plan_slug,published) values ('nivel_detalle','{"en":"Detail level","es":"Nivel de detalle","pt":"Nível de detalhe"}'::jsonb,'[{"en":"extremely detailed","es":"extremadamente detallado","pt":"extremamente detalhado"},{"en":"ultra detailed","es":"ultra detallado","pt":"ultra detalhado"},{"en":"rich in micro-details","es":"rico en micro-detalles","pt":"rico em micro-detalhes"},{"en":"fine architectural detailing","es":"detalles arquitectónicos finos","pt":"detalhamento arquitetônico fino"},{"en":"high texture fidelity","es":"alta fidelidad de texturas","pt":"alta fidelidade de texturas"},{"en":"crisp edges","es":"bordes nítidos","pt":"arestas nítidas"},{"en":"sharp focus","es":"foco nítido","pt":"foco nítido"},{"en":"realistic imperfections","es":"imperfecciones realistas","pt":"imperfeições realistas"},{"en":"authentic material aging","es":"envejecimiento auténtico de materiales","pt":"envelhecimento autêntico de materiais"},{"en":"high-resolution details","es":"detalles de alta resolución","pt":"detalhes de alta resolução"},{"en":"intricate surface details","es":"detalles superficiales intrincados","pt":"detalhes de superfície intrincados"},{"en":"detailed landscaping","es":"paisajismo detallado","pt":"paisagismo detalhado"}]'::jsonb,'["extremely detailed","high texture fidelity","sharp focus"]'::jsonb,2,'studio_pro',true) on conflict (key) do update set labels=excluded.labels,tags=excluded.tags,optimal_tags=excluded.optimal_tags,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
insert into public.quality_groups (key,labels,tags,optimal_tags,sort_order,required_plan_slug,published) values ('acabado_fotografico','{"en":"Photographic finish","es":"Acabado fotográfico","pt":"Acabamento fotográfico"}'::jsonb,'[{"en":"indistinguishable from real photography","es":"indistinguible de fotografía real","pt":"indistinguível de fotografia real"},{"en":"DSLR-quality photograph","es":"fotografía calidad DSLR","pt":"fotografia qualidade DSLR"},{"en":"medium-format photography","es":"fotografía de formato medio","pt":"fotografia de médio formato"},{"en":"editorial-quality architecture photography","es":"fotografía de arquitectura editorial","pt":"fotografia de arquitetura editorial"},{"en":"magazine-quality image","es":"imagen calidad revista","pt":"imagem qualidade revista"},{"en":"Architectural Digest quality","es":"calidad Architectural Digest","pt":"qualidade Architectural Digest"},{"en":"Dezeen editorial style","es":"estilo editorial Dezeen","pt":"estilo editorial Dezeen"},{"en":"ArchDaily publication quality","es":"calidad publicación ArchDaily","pt":"qualidade publicação ArchDaily"},{"en":"professional commercial photography","es":"fotografía comercial profesional","pt":"fotografia comercial profissional"},{"en":"luxury real estate marketing image","es":"imagen de marketing inmobiliario de lujo","pt":"imagem de marketing imobiliário de luxo"}]'::jsonb,'["indistinguishable from real photography","editorial-quality architecture photography"]'::jsonb,3,'studio_pro',true) on conflict (key) do update set labels=excluded.labels,tags=excluded.tags,optimal_tags=excluded.optimal_tags,sort_order=excluded.sort_order,required_plan_slug=excluded.required_plan_slug,published=excluded.published;
